  renderProjectTasks=function(p,tasks){const workstreams=p.workstreams.map(w=>w.name);return `<div class="section-row" style="margin-top:0"><div><h2>All project tasks</h2><p>${tasks.length} tasks across ${workstreams.length} categories.</p></div><div class="filters">${p.workstreams.length?'<button class="btn btn-soft" id="newTaskBtn">+ New Task</button>':''}<select class="select" id="projectWorkstreamFilter"><option value="">All Categories</option>${workstreams.map(w=>`<option value="${escapeHtml(w)}">${escapeHtml(w)}</option>`).join('')}</select><select class="select" id="projectStatusFilter"><option value="">All Statuses</option>${[...new Set(tasks.map(t=>t.status))].map(st=>`<option value="${escapeHtml(st)}">${escapeHtml(st)}</option>`).join('')}</select></div></div><div class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Task</th><th>Owner</th><th>Category Owner</th><th>Priority</th><th>Status</th><th>Progress</th><th>Due</th></tr></thead><tbody id="projectTaskRows">${tasks.map(t=>{const progress=Math.max(0,Math.min(100,Number(t.progress)||0));return `<tr data-task-row="${escapeHtml(t.id)}" data-workstream="${escapeHtml(t.workstream)}" data-status="${escapeHtml(t.status)}"><td><button class="task-link" data-task="${escapeHtml(t.id)}">${escapeHtml(t.title)}</button><div class="subtle">${escapeHtml(t.workstream)} • ${escapeHtml(t.deliverable)}</div></td><td>${person(t.owner)}</td><td>${escapeHtml(user(wsOwner(p,t.workstream)).name)}</td><td>${priorityPill(t.priority)}</td><td>${statusPill(isOverdue(t)?'Overdue':t.status)}</td><td><div class="progress-wrap"><div class="progress"><span style="width:${progress}%"></span></div><div class="percent">${progress}%</div></div></td><td>${fmtDate(t.currentDue)}${t.originalDue!==t.currentDue?`<div class="subtle">Original ${fmtDate(t.originalDue)}</div>`:''}</td></tr>`}).join('')}</tbody></table></div></div>`};

