  attentionItems=function(){const visibleIds=new Set(visibleProjects().map(p=>p.id)),items=[];state.approvals.filter(a=>{const t=task(a.task);return t&&visibleIds.has(t.project)&&(canApproveTask(t)||a.requestedBy===state.currentUser)}).slice(0,2).forEach(a=>{const t=task(a.task);items.push(`<div class="attention-item"><strong>${a.type}: ${t.title}</strong><span>${user(a.requestedBy).name} • ${project(t.project).name}</span><div class="row">${priorityPill(t.priority)}<button class="link-btn" data-task="${t.id}">Review →</button></div></div>`)});state.tasks.filter(t=>visibleIds.has(t.project)&&isOverdue(t)).slice(0,2).forEach(t=>items.push(`<div class="attention-item"><strong>${t.title}</strong><span>Overdue • ${user(t.owner).name} • ${project(t.project).name}</span><div class="row">${priorityPill(t.priority)}<button class="link-btn" data-task="${t.id}">Open →</button></div></div>`));return items.join('')||'<div class="empty"><strong>Nothing urgent</strong>Your desk is clear.</div>'};

